import React, { useEffect, useRef, useState } from "react";

/**
 * WallKhattab — wallpaper gallery component
 *
 * Drop this into a React (or Next.js) project. It's self-contained:
 * styles are injected via a <style> tag, so no external CSS file is needed.
 * Uses Google Fonts (Tajawal / IBM Plex Sans Arabic) — load them globally
 * in your app's <head>, or add <link> tags yourself.
 *
 * NOTE: SUNSET_GLOW_SRC below is a base64-embedded JPEG so this file stays
 * fully self-contained. In a real project you'll likely want to replace it
 * with a normal asset import instead, e.g.:
 *   import sunsetGlow from "./assets/sunset-glow.jpg";
 * and then use `src: sunsetGlow` in WALLPAPERS.
 */

