function drawGradient(canvas: HTMLCanvasElement, wall: Wallpaper) {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const w = (canvas.width = 360);
  const h = (canvas.height = 640);

  if (wall.type === "blob") {
    ctx.fillStyle = wall.colors![2];
    ctx.fillRect(0, 0, w, h);
    const g1 = ctx.createRadialGradient(w * 0.35, h * 0.3, 10, w * 0.35, h * 0.3, w * 0.9);
    g1.addColorStop(0, wall.colors![0]);
    g1.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g1;
    ctx.fillRect(0, 0, w, h);
    const g2 = ctx.createRadialGradient(w * 0.55, h * 0.65, 10, w * 0.55, h * 0.65, w * 0.85);
    g2.addColorStop(0, wall.colors![1]);
    g2.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g2;
    ctx.fillRect(0, 0, w, h);
  } else if (wall.type === "linear") {
    const g = ctx.createLinearGradient(0, 0, w * 0.4, h);
    wall.colors!.forEach((c, i) => g.addColorStop(i / (wall.colors!.length - 1), c));
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }
}

function getWallDataUrl(wall: Wallpaper, canvas: HTMLCanvasElement | null): string | null {
  if (wall.type === "image") return wall.src ?? null;
  if (canvas) return canvas.toDataURL("image/png");
  return null;
}

function WallpaperCard({
  wall,
  active,
  onActivate,
  onOpenViewer,
}: {
  wall: Wallpaper;
  active: boolean;
  onActivate: (id: string | null) => void;
  onOpenViewer: (wall: Wallpaper, canvas: HTMLCanvasElement | null) => void;
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const lastTap = useRef(0);

  // نقرة واحدة = إظهار/إخفاء زر التحميل، نقرتان متتاليتان = عارض الصورة
  const handleCardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    const now = Date.now();
    if (now - lastTap.current < 320) {
      lastTap.current = 0;
      onActivate(null);
      onOpenViewer(wall, canvasRef.current);
    } else {
      lastTap.current = now;
      onActivate(active ? null : wall.id);
    }
  };

  useEffect(() => {
    if (wall.type !== "image" && canvasRef.current) drawGradient(canvasRef.current, wall);
  }, [wall]);

  const handleDownload = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (wall.link) {
      window.open(wall.link, "_blank", "noopener");
      return;
    }
    const url = getWallDataUrl(wall, canvasRef.current);
    if (!url) return;
    const link = document.createElement("a");
    link.download = `${wall.id}.png`;
    link.href = url;
    link.click();
  };

  return (
    <div className="wk-card" onClick={handleCardClick}>
      {wall.type === "image" ? (
        <img src={wall.src} alt={wall.id} />
      ) : (
        <canvas ref={canvasRef} />
      )}
      <div className="wk-noise" />
      <button className={`wk-dl${active ? " show" : ""}`} onClick={handleDownload} tabIndex={active ? 0 : -1}>
        تحميل
      </button>
    </div>
  );
}

function WallViewer({
  wall,
  previewUrl,
  onClose,
}: {
  wall: Wallpaper;
  previewUrl: string | null;
  onClose: () => void;
}) {
  const handleDownload = () => {
    if (wall.link) {
      window.open(wall.link, "_blank", "noopener");
      return;
    }
    if (!previewUrl) return;
    const link = document.createElement("a");
    link.download = `${wall.id}.png`;
    link.href = previewUrl;
    link.click();
  };

  return (
    <div className="wk-viewer" onClick={onClose}>
      {previewUrl && <div className="wk-viewer-bg" style={{ backgroundImage: `url("${previewUrl}")` }} />}
      <div className="wk-viewer-stack" onClick={(e) => e.stopPropagation()}>
        <div className="wk-viewer-img">{previewUrl && <img src={previewUrl} alt={wall.id} />}</div>
        <div className="wk-viewer-btns">
          <button className="wk-viewer-dl" onClick={handleDownload}>تحميل</button>
          <button className="wk-viewer-close" onClick={onClose}>اغلاق</button>
        </div>
      </div>
    </div>
  );
}

