const CP_PASSWORD = "Khattab@2026";
const LS_CUSTOM = "wk-custom-walls";
const LS_HIDDEN = "wk-hidden-walls";
const LS_SOCIALS = "wk-social-links";

function lsSave(key: string, value: unknown): boolean {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}

function lsLoad<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
}

function fileToDataUrl(file: File, maxSide = 1600): Promise<string> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
      const c = document.createElement("canvas");
      c.width = Math.round(img.width * scale);
      c.height = Math.round(img.height * scale);
      const ctx = c.getContext("2d");
      if (!ctx) {
        URL.revokeObjectURL(url);
        reject(new Error("canvas"));
        return;
      }
      ctx.drawImage(img, 0, 0, c.width, c.height);
      URL.revokeObjectURL(url);
      resolve(c.toDataURL("image/jpeg", 0.85));
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("load"));
    };
    img.src = url;
  });
}

function ControlLogin({ onSuccess, onCancel }: { onSuccess: () => void; onCancel: () => void }) {
  const [pw, setPw] = useState("");
  const [error, setError] = useState(false);
  const [shake, setShake] = useState(false);

  const submit = () => {
    if (pw === CP_PASSWORD) {
      onSuccess();
    } else {
      setError(true);
      setShake(true);
      setPw("");
    }
  };

  return (
    <div className="wk-cp-overlay" onClick={onCancel}>
      <div
        className={`wk-cp-dialog${shake ? " shake" : ""}`}
        onClick={(e) => e.stopPropagation()}
        onAnimationEnd={() => setShake(false)}
      >
        <h2>لوحة التحكم</h2>
        <p className="wk-cp-sub">أدخل كلمة السر للدخول</p>
        <input
          className={`wk-cp-input${error ? " err" : ""}`}
          type="password"
          dir="rtl"
          placeholder="كلمة السر"
          value={pw}
          autoFocus
          autoComplete="off"
          onChange={(e) => {
            setPw(e.target.value);
            setError(false);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") submit();
          }}
        />
        {error && <div className="wk-cp-error">كلمة السر غير صحيحة</div>}
        <button className="wk-cp-gold" onClick={submit}>
          دخول
        </button>
        <button className="wk-cp-ghost" onClick={onCancel}>
          إلغاء
        </button>
      </div>
    </div>
  );
}

function ControlPanel({
  walls,
  hiddenCount,
  socials,
  msg,
  onAdd,
  onDelete,
  onRestore,
  onSocial,
  onLogout,
  onClose,
}: {
  walls: Wallpaper[];
  hiddenCount: number;
  socials: { key: string; label: string; href: string }[];
  msg: string;
  onAdd: (file: File, link: string) => Promise<boolean>;
  onDelete: (id: string) => void;
  onRestore: () => void;
  onSocial: (key: string, value: string) => void;
  onLogout: () => void;
  onClose: () => void;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [confirmId, setConfirmId] = useState<string | null>(null);
  const [picked, setPicked] = useState<File | null>(null);
  const [pickedUrl, setPickedUrl] = useState<string | null>(null);
  const [link, setLink] = useState("");

  useEffect(() => {
    if (!picked) {
      setPickedUrl(null);
      return;
    }
    const url = URL.createObjectURL(picked);
    setPickedUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [picked]);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (file) setPicked(file);
  };

  const handleSave = async () => {
    if (!picked) return;
    setBusy(true);
    const ok = await onAdd(picked, link);
    setBusy(false);
    if (ok) {
      setPicked(null);
      setLink("");
    }
  };

  return (
    <div className="wk-cp-overlay" onClick={onClose}>
      <div className="wk-cp-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="wk-cp-head">
          <h2>لوحة التحكم</h2>
          <button className="wk-cp-x" aria-label="إغلاق" onClick={onClose}>
            ✕
          </button>
        </div>

        {msg && <div className="wk-cp-msg">{msg}</div>}

        <section>
          <h3>إضافة خلفية</h3>
          <input ref={fileRef} type="file" accept="image/*" hidden onChange={handleFile} />
          <button className="wk-cp-ghost wk-cp-pick" disabled={busy} onClick={() => fileRef.current?.click()}>
            {picked ? "تغيير الصورة" : "اختيار صورة من الجهاز"}
          </button>
          {picked && (
            <div className="wk-cp-row">
              <div className="wk-cp-thumb">{pickedUrl && <img src={pickedUrl} alt="" />}</div>
              <div className="wk-cp-name">{picked.name}</div>
            </div>
          )}
          <label className="wk-cp-field">
            <span>رابط تحميل الصورة (اختياري)</span>
            <input
              className="wk-cp-input small"
              dir="ltr"
              placeholder="https://..."
              value={link}
              onChange={(e) => setLink(e.target.value)}
            />
          </label>
          <button className="wk-cp-gold" disabled={busy || !picked} onClick={handleSave}>
            {busy ? "جارٍ الحفظ..." : "حفظ"}
          </button>
        </section>

        <section>
          <h3>الخلفيات ({walls.length})</h3>
          <div className="wk-cp-list">
            {walls.map((w) => (
              <div className="wk-cp-row" key={w.id}>
                <div
                  className="wk-cp-thumb"
                  style={w.type === "image" ? undefined : { background: `linear-gradient(160deg, ${w.colors!.join(", ")})` }}
                >
                  {w.type === "image" && <img src={w.src} alt={w.id} />}
                </div>
                <div className="wk-cp-name">{w.id.startsWith("custom-") ? "خلفية مضافة" : w.id}</div>
                {confirmId === w.id ? (
                  <button
                    className="wk-cp-del sure"
                    onClick={() => {
                      onDelete(w.id);
                      setConfirmId(null);
                    }}
                  >
                    تأكيد الحذف
                  </button>
                ) : (
                  <button className="wk-cp-del" onClick={() => setConfirmId(w.id)}>
                    حذف
                  </button>
                )}
              </div>
            ))}
            {walls.length === 0 && <div className="wk-cp-empty">لا توجد خلفيات</div>}
          </div>
          {hiddenCount > 0 && (
            <button className="wk-cp-ghost" onClick={onRestore}>
              استعادة الخلفيات المحذوفة ({hiddenCount})
            </button>
          )}
        </section>

        <section>
          <h3>روابط التواصل</h3>
          {socials.map((s) => (
            <label className="wk-cp-field" key={s.key}>
              <span>{s.label}</span>
              <input
                className="wk-cp-input small"
                dir="ltr"
                value={s.href}
                onChange={(e) => onSocial(s.key, e.target.value)}
              />
            </label>
          ))}
        </section>

        <button className="wk-cp-ghost" onClick={onLogout}>
          تسجيل الخروج
        </button>
      </div>
    </div>
  );
}

